const designs=[{id:'bloom',name:'花开满怀',sub:'让每一天，都开出一点小欢喜。',tag:'趣味',category:'play',bg:'#efe3fa',color:'#2eb4b6',art:'flower'},{id:'type',name:'我的宣言',sub:'用你的方式，表达自己。',tag:'简约',category:'simple',bg:'#eee5e5',color:'#fff3e4',art:'type'},{id:'abstract',name:'不拘一格',sub:'日常，也可以有点不一样。',tag:'趣味',category:'play',bg:'#eae6f0',color:'#dbcef0',art:'wave'},{id:'sunset',name:'慢时光',sub:'把温柔，留给每一个平常日子。',tag:'治愈',category:'warm',bg:'#f2e8dc',color:'#f6c9a8',art:'sun'}];
function pattern(d){const start=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 176 342"><rect width="176" height="342" fill="${d.color}"/>`;let art='';if(d.art==='flower'){for(const [x,y] of [[110,132],[55,274]]){art+=`<g transform="translate(${x} ${y})">`;for(let a=0;a<360;a+=60)art+=`<ellipse cy="-23" rx="13" ry="25" fill="#e64294" transform="rotate(${a})"/>`;art+='<circle r="17" fill="#fff4de"/></g>';}art+='<text x="97" y="323" text-anchor="middle" font-family="Georgia" font-weight="bold" font-size="22" fill="#233d34">bloom.</text>';}else if(d.art==='type'){art='<g font-family="Arial" font-size="29" font-weight="900" text-anchor="middle" fill="#d4498e"><text x="88" y="148">MAKE</text><text x="88" y="204">IT</text><text x="88" y="260">YOURS.</text></g>';}else if(d.art==='wave'){art='<g fill="none" stroke="#26b4b3" stroke-width="10" stroke-linecap="round"><path d="M-10 150Q20 110 48 145T105 145T185 145M-10 185Q20 145 48 180T105 180T185 180M-10 220Q20 180 48 215T105 215T185 215"/></g><g font-family="Georgia" font-size="21" font-weight="bold" text-anchor="middle" fill="#233d34"><text x="88" y="282">a little</text><text x="88" y="307">different.</text></g>';}else art='<circle cx="115" cy="151" r="42" fill="#ef8c65"/><path d="M0 225Q75 153 176 225V342H0" fill="#e7a17e"/><path d="M0 275Q85 202 176 258V342H0" fill="#789d8b"/><text x="88" y="318" text-anchor="middle" font-family="Georgia" font-style="italic" font-size="22" fill="#fff6e9">slow days.</text>';return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(start+art+'</svg>');}
const grid=document.querySelector('#design-grid');
grid.innerHTML=designs.map((d,i)=>`<article class="design-card" data-category="${d.category}"><button class="design-art" style="--card-bg:${d.bg}" data-design="${i}" aria-label="预览${d.name}"><span class="card-number">0${i+1}</span><div class="phone"><div class="phone-image"></div><div class="camera"><i></i><i></i><i></i><b></b></div></div><span class="card-arrow" aria-hidden="true">↗</span></button><h3>${d.name}<span>${d.tag}</span></h3><p>${d.sub}</p></article>`).join('');
grid.querySelectorAll('.phone-image').forEach((el,i)=>el.style.backgroundImage=`url("${pattern(designs[i])}")`);
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});let count=0;document.querySelectorAll('.design-card').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter;if(!card.hidden)count++;});document.querySelector('#result-count').textContent=`${count} 款精选`;}));
const modal=document.querySelector('#preview-dialog'),draftModal=document.querySelector('#draft-dialog'),fileInput=document.querySelector('#photo-input'),photo=document.querySelector('.preview-phone .phone-image'),zoom=document.querySelector('#zoom'),position=document.querySelector('#position');let currentImage='assets/pet.png',currentName='我的照片设计',draft=null,objectUrl=null,toastTimer,currentSource='photo',currentTemplate=null,editingId=null,selectedHomeModel=null;
let savedDesigns=[];try{savedDesigns=JSON.parse(sessionStorage.getItem('popomo-home-designs')||'[]');if(!Array.isArray(savedDesigns))savedDesigns=[];}catch{}
const homeText=(zh,en)=>document.documentElement.lang.startsWith('en')?en:zh;
function updateDesignCount(){document.querySelector('#draft-count').textContent=savedDesigns.length;}updateDesignCount();
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000);}
function openPreview(src,name,metadata={}){currentImage=src;currentName=name;currentSource=metadata.source||'photo';currentTemplate=metadata.template||null;editingId=metadata.id||null;document.querySelector('#preview-title').textContent=currentSource==='template'?homeText('把喜欢的设计，带在身边。','Keep your favorite design close.'):homeText('喜欢的照片，变成喜欢的壳。','Your favorite photo. Your favorite case.');photo.style.backgroundImage=`url("${src}")`;zoom.value=100;position.value=50;adjust();if(!modal.open)modal.showModal();}
function adjust(){photo.style.backgroundSize='cover';photo.style.transform=`scale(${Number(zoom.value)/100})`;photo.style.backgroundPosition=`50% ${position.value}%`;document.querySelector('#zoom-output').value=zoom.value+'%';}
zoom.addEventListener('input',adjust);position.addEventListener('input',adjust);
document.querySelectorAll('[data-upload]').forEach(b=>b.addEventListener('click',()=>{if(b.closest('#preview-dialog')){fileInput.value='';fileInput.click();}else window.dispatchEvent(new CustomEvent('popomo-start',{detail:{type:'photo'}}));}));
function loadPhoto(f){if(f)window.dispatchEvent(new CustomEvent('popomo-start',{detail:{type:'photo',file:f}}));}
fileInput.addEventListener('change',()=>loadPhoto(fileInput.files[0]));
grid.querySelectorAll('[data-design]').forEach(b=>b.addEventListener('click',()=>{window.dispatchEvent(new CustomEvent('popomo-start',{detail:{type:'template',index:Number(b.dataset.design)}}));}));
document.querySelectorAll('.close-btn').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
function currentDesign(){return {id:editingId||crypto.randomUUID(),image:currentImage,name:currentName,source:currentSource,template:currentTemplate,zoom:Number(zoom.value),position:Number(position.value),model:selectedHomeModel?.name||'',phoneColor:selectedHomeModel?.phoneColor||'blue',printerId:window.PopomoPrinterSelection?.get()?.id};}
function saveHomeDesign(design){try{const next=window.PopomoDesigns.save(design);savedDesigns=window.PopomoDesigns.list();editingId=next.id;updateDesignCount();if(modal.open)modal.close();toast(homeText('设计已保存，可从我的设计继续编辑','Design saved. Continue editing from My designs.'));return true;}catch{toast(homeText('保存空间不足，请使用高级定制继续','Storage is full. Continue with advanced customization.'));return false;}}

async function prepareBackground(design){if(design.source==='template')return design.image;const image=new Image();image.src=design.image;await image.decode();const canvas=document.createElement('canvas');canvas.width=660;canvas.height=1282;const context=canvas.getContext('2d'),scale=Math.max(canvas.width/image.width,canvas.height/image.height),baseW=image.width*scale,baseH=image.height*scale,z=design.zoom/100;context.drawImage(image,canvas.width/2+((canvas.width-baseW)/2-canvas.width/2)*z,canvas.height/2+((canvas.height-baseH)*design.position/100-canvas.height/2)*z,baseW*z,baseH*z);return canvas.toDataURL('image/jpeg',.92);}
async function advancedHomeDesign(design){const button=document.querySelector('#advanced-design');if(button)button.disabled=true;try{const entry={...design,designId:design.id||null,id:crypto.randomUUID(),backgroundImage:await prepareBackground(design)};sessionStorage.setItem('popomo-design-entry',JSON.stringify(entry));location.href='./customize.html?entry='+encodeURIComponent(entry.id)+'#design';}catch{toast(homeText('暂时无法打开，请重新选择照片','Could not open. Please choose your photo again.'));if(button)button.disabled=false;}}
document.querySelector('#save-draft').addEventListener('click',()=>saveHomeDesign(currentDesign()));
document.querySelector('#advanced-design').addEventListener('click',()=>advancedHomeDesign(currentDesign()));
document.querySelector('#draft-button').addEventListener('click',()=>{location.href='./my-designs.html';});
function setHomeModel(model){selectedHomeModel=model;const shell=document.querySelector('.preview-phone');shell.classList.add('has-real-model');shell.style.setProperty('--case-ratio',model.width/model.height);let mask=shell.querySelector('.home-print-mask');if(!mask){mask=document.createElement('div');mask.className='home-print-mask';photo.before(mask);mask.append(photo);const overlay=document.createElement('img');overlay.className='home-case-overlay';overlay.alt=model.name;shell.append(overlay);}mask.style.maskImage=mask.style.webkitMaskImage=`url('${model.mask}')`;const overlay=shell.querySelector('.home-case-overlay');overlay.src=model.overlay;overlay.alt=model.name;let label=document.querySelector('.home-preview-model');if(!label){label=document.createElement('p');label.className='home-preview-model';document.querySelector('#preview-title').before(label);}label.textContent=model.name+(window.PopomoPhoneModels?' · '+homeText(window.PopomoPhoneModels.phoneColor(model.phoneColor).zh,window.PopomoPhoneModels.phoneColor(model.phoneColor).en):'');}
window.popomoHome={save:saveHomeDesign,advanced:advancedHomeDesign,notify:toast,setModel:setHomeModel,loadPhotoFile:loadPhoto,previewSaved(design){openPreview(design.image,design.name,design);zoom.value=design.zoom;position.value=design.position;adjust();},pickPhoto(){fileInput.value='';fileInput.click();},previewTemplate(index){const design=designs[index];openPreview(pattern(design),design.name,{source:'template',template:design.id});}};
window.addEventListener('pageshow',()=>{document.querySelector('#advanced-design').disabled=false;});
